{"command": "cd logs
python3 - <<'EOF'
import glob, collections
for f in sorted(glob.glob('*.log')):
    svc=f[:-4]
    d=collections.OrderedDict()
    for line in open(f):
        if '[ERROR]' in line:
            parts=line.split()
            # 0=date 1=time 2=[ERROR] 3=service 4=code
            code=parts[4]
            fullts=parts[0]+' '+parts[1]
            if code not in d:
                d[code]=[0,fullts]
            d[code][0]+=1
    print(f'== {svc} ==')
    for code,(cnt,first) in sorted(d.items()):
        print(f'  {code} count={cnt} first={first}')
EOF", "description": "Parse codes per service fixed"}
